'use client';

import { useEffect, useState } from 'react';
import Hero from './components/Hero';
import Projects from './components/Projects';
import Skills from './components/Skills';
import Experience from './components/Experience';
import Testimonials from './components/Testimonials';
import Contact from './components/Contact';
import Navigation from './components/Navigation';
import { Project, Skill, Experience as ExperienceType, Contact as ContactType, Testimonial } from './utils/data';

export default function Home() {
  const [projects, setProjects] = useState<Project[]>([]);
  const [skills, setSkills] = useState<Skill[]>([]);
  const [experience, setExperience] = useState<ExperienceType[]>([]);
  const [contact, setContact] = useState<ContactType | null>(null);
  const [testimonials, setTestimonials] = useState<Testimonial[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchData = async () => {
      try {
        const [projectsRes, skillsRes, experienceRes, contactRes, testimonialsRes] = await Promise.all([
          fetch('http://localhost:5000/api/projects'),
          fetch('http://localhost:5000/api/skills'),
          fetch('http://localhost:5000/api/experience'),
          fetch('http://localhost:5000/api/contact'),
          fetch('http://localhost:5000/api/testimonials')
        ]);

        const projectsData = await projectsRes.json();
        const skillsData = await skillsRes.json();
        const experienceData = await experienceRes.json();
        const contactData = await contactRes.json();
        const testimonialsData = await testimonialsRes.json();

        setProjects(projectsData.data);
        setSkills(skillsData.data);
        setExperience(experienceData.data);
        setContact(contactData.data);
        setTestimonials(testimonialsData.data);
      } catch (error) {
        console.error('Error fetching data:', error);
      } finally {
        setLoading(false);
      }
    };

    fetchData();
  }, []);

  if (loading) {
    return (
      <div className="min-h-screen flex items-center justify-center bg-background">
        <div className="animate-spin rounded-full h-12 w-12 border-t-2 border-b-2 border-primary"></div>
      </div>
    );
  }

  return (
    <main className="min-h-screen bg-background">
      <Navigation />
      <Hero contact={contact} />
      <Projects projects={projects} />
      <Skills skills={skills} />
      <Experience experience={experience} />
      <Testimonials testimonials={testimonials} />
      <Contact contact={contact} />
    </main>
  );
}

